#define _GNU_SOURCE
#include <dlfcn.h>
#include <errno.h>
#include <fcntl.h>
#include <linux/kvm.h>
#include <pthread.h>
#include <stdarg.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <time.h>
#include <unistd.h>

static int (*next_ioctl)(int, unsigned long, ...);
static void *(*next_mmap)(void *, size_t, int, int, int, off_t);
static _Atomic(struct kvm_run *) runs[65536];
static _Atomic int vcpus[65536];
static _Atomic int statistics[256];
static _Atomic uint64_t exits[128];
static _Atomic uint64_t vram_exits;
static _Atomic uint64_t mmio_pages[1 << 20];
static _Atomic int stop;
static FILE *output;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_t observer;

static double timestamp(void) {
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec / 1e9;
}

static void sample(void) {
    pthread_mutex_lock(&lock);
    for (int id = 0; id < 256; id++) {
        int fd = statistics[id];
        if (fd <= 0) continue;
        struct kvm_stats_header header;
        if (pread(fd, &header, sizeof(header), 0) != sizeof(header)) continue;
        if (header.num_desc > 4096 || header.name_size > 1024) continue;
        size_t stride = sizeof(struct kvm_stats_desc) + header.name_size;
        char *descriptors = malloc(stride * header.num_desc);
        if (!descriptors) continue;
        if (pread(fd, descriptors, stride * header.num_desc, header.desc_offset) != (ssize_t)(stride * header.num_desc)) {
            free(descriptors);
            continue;
        }
        fprintf(output, "{\"kind\":\"stats\",\"t\":%.9f,\"vcpu\":%d,\"values\":{", timestamp(), id);
        int comma = 0;
        for (unsigned i = 0; i < header.num_desc; i++) {
            struct kvm_stats_desc *d = (void *)(descriptors + i * stride);
            if (d->size > 128) continue;
            uint64_t values[128];
            size_t bytes = d->size * sizeof(uint64_t);
            if (pread(fd, values, bytes, header.data_offset + d->offset) != (ssize_t)bytes) continue;
            fprintf(output, "%s\"%.*s\":[", comma++ ? "," : "", (int)header.name_size, d->name);
            for (unsigned j = 0; j < d->size; j++) fprintf(output, "%s%lu", j ? "," : "", (unsigned long)values[j]);
            fputc(']', output);
        }
        fprintf(output, "}}\n");
        free(descriptors);
    }
    fprintf(output, "{\"kind\":\"userspace_exits\",\"t\":%.9f,\"vram\":%lu,\"values\":{", timestamp(), (unsigned long)vram_exits);
    int comma = 0;
    for (int i = 0; i < 128; i++) {
        uint64_t count = exits[i];
        if (count) fprintf(output, "%s\"%d\":%lu", comma++ ? "," : "", i, (unsigned long)count);
    }
    fprintf(output, "}}\n");
    fflush(output);
    pthread_mutex_unlock(&lock);
}

static void *observe(void *unused) {
    (void)unused;
    while (!stop) {
        sample();
        struct timespec wait = {.tv_sec = 1};
        nanosleep(&wait, NULL);
    }
    return NULL;
}

__attribute__((constructor)) static void initialize(void) {
    next_ioctl = dlsym(RTLD_NEXT, "ioctl");
    next_mmap = dlsym(RTLD_NEXT, "mmap");
    const char *path = getenv("PERF5_OBSERVE");
    if (!path) return;
    output = fopen(path, "w");
    if (output) pthread_create(&observer, NULL, observe, NULL);
}

int ioctl(int fd, unsigned long request, ...) {
    va_list args;
    va_start(args, request);
    unsigned long arg = va_arg(args, unsigned long);
    va_end(args);
    int result = next_ioctl(fd, request, arg);
    int saved_errno = errno;
    if (!output) return result;
    if (request == KVM_CREATE_VCPU && result >= 0 && result < 65536) {
        vcpus[result] = 1;
        if (arg < 256) statistics[arg] = next_ioctl(result, KVM_GET_STATS_FD, 0);
    }
    if (request == KVM_RUN && result == 0 && fd >= 0 && fd < 65536) {
        struct kvm_run *run = runs[fd];
        if (run) {
            if (run->exit_reason < 128) exits[run->exit_reason]++;
            if (run->exit_reason == KVM_EXIT_MMIO && run->mmio.phys_addr >= 0xc0000000 && run->mmio.phys_addr < 0xe0000000) vram_exits++;
            if (run->exit_reason == KVM_EXIT_MMIO && (run->mmio.phys_addr >> 12) < (1 << 20)) mmio_pages[run->mmio.phys_addr >> 12]++;
        }
    }
    if (result == 0 && request == KVM_SET_CPUID2) {
        struct kvm_cpuid2 *cpuid = (void *)arg;
        pthread_mutex_lock(&lock);
        for (unsigned i = 0; i < cpuid->nent; i++) {
            struct kvm_cpuid_entry2 *e = &cpuid->entries[i];
            if (e->function < 0x40000000 || e->function > 0x40000101) continue;
            fprintf(output, "{\"kind\":\"cpuid\",\"fd\":%d,\"function\":%u,\"index\":%u,\"registers\":[%u,%u,%u,%u]}\n", fd, e->function, e->index, e->eax,e->ebx,e->ecx,e->edx);
        }
        fflush(output);
        pthread_mutex_unlock(&lock);
    }
    if (result == 0 && request == KVM_SET_USER_MEMORY_REGION) {
        struct kvm_userspace_memory_region *r = (void *)arg;
        pthread_mutex_lock(&lock);
        fprintf(output, "{\"kind\":\"memory\",\"t\":%.9f,\"slot\":%u,\"flags\":%u,\"gpa\":%lu,\"size\":%lu}\n", timestamp(), r->slot,r->flags,(unsigned long)r->guest_phys_addr,(unsigned long)r->memory_size);
        pthread_mutex_unlock(&lock);
    }
    if (result == 0 && (request == KVM_CREATE_IRQCHIP || request == KVM_CREATE_PIT2 || request == KVM_ENABLE_CAP || request == KVM_REINJECT_CONTROL)) {
        pthread_mutex_lock(&lock);
        fprintf(output, "{\"kind\":\"configure\",\"fd\":%d,\"request\":%lu",fd,request);
        if (request == KVM_ENABLE_CAP) fprintf(output, ",\"cap\":%u", ((struct kvm_enable_cap *)arg)->cap);
        if (request == KVM_REINJECT_CONTROL) fprintf(output, ",\"pit_reinject\":%u", ((struct kvm_reinject_control *)arg)->pit_reinject);
        fprintf(output, "}\n");
        pthread_mutex_unlock(&lock);
    }
    errno = saved_errno;
    return result;
}

void *mmap(void *address, size_t size, int prot, int flags, int fd, off_t offset) {
    void *result = next_mmap(address, size, prot, flags, fd, offset);
    if (fd >= 0 && fd < 65536 && vcpus[fd] && offset == 0 && result != MAP_FAILED) runs[fd] = result;
    return result;
}

void *mmap64(void *address, size_t size, int prot, int flags, int fd, off64_t offset) {
    return mmap(address, size, prot, flags, fd, offset);
}

__attribute__((destructor)) static void finish(void) {
    if (!output) return;
    stop = 1;
    pthread_join(observer, NULL);
    sample();
    for (int i = 0; i < (1 << 20); i++) {
        uint64_t count = mmio_pages[i];
        if (count) fprintf(output, "{\"kind\":\"mmio_page\",\"address\":%lu,\"count\":%lu}\n", (unsigned long)i << 12, (unsigned long)count);
    }
    fclose(output);
}
